  1	// Debate config (Kaizen v0): `--config debate.yaml` selects the participant
  2	// lineup so each run can choose adapters that match the target repository policy.
  3	//
  4	// This parses a deliberately MINIMAL YAML subset — flat top-level scalars plus
  5	// one `participants:` list of flat maps — with strict, line-numbered errors.
  6	// No dependency, no build step (the repo's standing rule). When config needs
  7	// real YAML (nesting, anchors), switch to a parser library; do not grow this.
  8	
  9	export type AdapterId = "claude" | "agy" | "codex" | "pi" | "copilot-cli";
 10	
 11	export type ParticipantSpec = {
 12	  adapter: AdapterId;
 13	  model?: string;        // omit = the adapter's default (codex: the account default)
 14	  bin?: string;          // override the binary path (e.g. a shadowed codex install)
 15	  maxBudgetUsd?: number; // claude only
 16	  effort?: string;       // reasoning effort, to dose token spend. claude: --effort
 17	                         // (low|medium|high|xhigh|max); codex: model_reasoning_effort
 18	                         // (minimal|low|medium|high). NOT supported by agy (effort is
 19	                         // baked into the model name, e.g. "Gemini 3.5 Flash (High)").
 20	                         // Free-form string: the CLI validates it (errors surface in
 21	                         // the raw capture / --doctor), so this parser stays version-agnostic.
 22	};
 23	
 24	export type DebateConfig = {
 25	  rounds?: number;
 26	  repo?: string;
 27	  timeoutMinutes?: number;
 28	  participants?: ParticipantSpec[];
 29	  judge?: ParticipantSpec; // the respondeo agent: renders the consolidatio (opt-in)
 30	};
 31	
 32	// The inverse of parseDebateConfig: emit the same minimal YAML subset this module
 33	// parses, so a generated config round-trips back through parseDebateConfig unchanged.
 34	// Used by `disputatio --init` to write ~/.config/disputatio/config.yaml. Keep it in
 35	// lock-step with the parser — if one grows a key, so must the other (round-trip test).
 36	const PARTICIPANT_ORDER: (keyof ParticipantSpec)[] = ["adapter", "model", "bin", "maxBudgetUsd", "effort"];
 37	
 38	// Quote a scalar only when leaving it bare would change how the parser reads it — namely
 39	// edge whitespace or an empty value (both eaten by the parser otherwise). Plain values
 40	// like model names with spaces/parens ("Gemini 3.5 Flash (High)") stay unquoted; the
 41	// parser reads the whole rest-of-line. A value with a `(^|\s)#` is UNREPRESENTABLE — the
 42	// parser strips trailing comments before handling quotes, so quoting can't save it; we
 43	// refuse it loudly rather than write config that silently round-trips to something else.
 44	function emitScalar(v: string | number): string {
 45	  if (typeof v === "number") return String(v);
 46	  if (/(^|\s)#/.test(v)) throw new Error(`config value cannot contain a "#" comment marker: ${JSON.stringify(v)}`);
 47	  return v === "" || v !== v.trim() ? JSON.stringify(v) : v;
 48	}
 49	
 50	function emitSpec(spec: ParticipantSpec, indent: string, firstPrefix: string): string {
 51	  const lines: string[] = [];
 52	  let prefix = firstPrefix;
 53	  for (const key of PARTICIPANT_ORDER) {
 54	    const val = spec[key];
 55	    if (val === undefined) continue;
 56	    lines.push(`${prefix}${key}: ${emitScalar(val)}`);
 57	    prefix = indent; // only the first key carries the "- " list marker
 58	  }
 59	  return lines.join("\n");
 60	}
 61	
 62	export function serializeDebateConfig(cfg: DebateConfig): string {
 63	  const out: string[] = [];
 64	  if (cfg.rounds !== undefined) out.push(`rounds: ${cfg.rounds}`);
 65	  if (cfg.timeoutMinutes !== undefined) out.push(`timeoutMinutes: ${cfg.timeoutMinutes}`);
 66	  if (cfg.repo !== undefined) out.push(`repo: ${emitScalar(cfg.repo)}`);
 67	  if (cfg.participants) {
 68	    out.push("participants:");
 69	    for (const p of cfg.participants) out.push(emitSpec(p, "    ", "  - "));
 70	  }
 71	  if (cfg.judge) {
 72	    out.push("judge:");
 73	    out.push(emitSpec(cfg.judge, "  ", "  "));
 74	  }
 75	  return out.join("\n") + "\n";
 76	}
 77	
 78	const ADAPTERS = new Set<string>(["claude", "agy", "codex", "pi", "copilot-cli"]);
 79	const TOP_KEYS = new Set<string>(["rounds", "repo", "timeoutMinutes", "participants", "judge"]);
 80	const PARTICIPANT_KEYS = new Set<string>(["adapter", "model", "bin", "maxBudgetUsd", "effort"]);
 81	const NUMERIC_KEYS = new Set<string>(["rounds", "timeoutMinutes", "maxBudgetUsd"]);
 82	
 83	function fail(lineNo: number, msg: string): never {
 84	  throw new Error(`debate config line ${lineNo}: ${msg}`);
 85	}
 86	
 87	function scalar(raw: string, key: string, lineNo: number): string | number {
 88	  let v = raw.trim();
 89	  const quoted = (v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"));
 90	  if (quoted) v = v.slice(1, -1);
 91	  if (v === "") fail(lineNo, `key "${key}" has no value`);
 92	  if (NUMERIC_KEYS.has(key)) {
 93	    const n = Number(v);
 94	    if (!Number.isFinite(n)) fail(lineNo, `key "${key}" must be a number, got "${v}"`);
 95	    return n;
 96	  }
 97	  return v;
 98	}
 99	
100	export function parseDebateConfig(text: string): DebateConfig {
101	  const cfg: DebateConfig = {};
102	  let participants: Record<string, string | number>[] | null = null;
103	  // The judge is a single spec (not a list). The `in*` flags track which block's
104	  // continuation lines we are currently reading; any new top-level key closes both
105	  // (so the accumulators are NOT discarded — a later `judge:` must not drop the
106	  // already-parsed participants, nor a later top key the judge).
107	  let judge: Record<string, string | number> | null = null;
108	  let inParticipants = false;
109	  let inJudge = false;
110	
111	  const lines = text.split("\n");
112	  for (let i = 0; i < lines.length; i++) {
113	    const lineNo = i + 1;
114	    const noComment = lines[i].replace(/(^|\s)#.*$/, ""); // strip full-line & trailing comments
115	    if (noComment.trim() === "") continue;
116	
117	    const top = noComment.match(/^([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);          // key: value (indent 0)
118	    const item = noComment.match(/^\s+-\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);  //   - key: value
119	    const cont = noComment.match(/^\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);      //     key: value
120	
121	    if (top) {
122	      const [, key, rest] = top;
123	      if (!TOP_KEYS.has(key)) fail(lineNo, `unknown key "${key}" (known: ${[...TOP_KEYS].join(", ")})`);
124	      // A new top-level key always ends the current block (but keeps its accumulator).
125	      inParticipants = key === "participants";
126	      inJudge = key === "judge";
127	      if (key === "participants") {
128	        if (rest.trim() !== "") fail(lineNo, `"participants" must be a list (put items on the following lines)`);
129	        participants = [];
130	      } else if (key === "judge") {
131	        if (rest.trim() !== "") fail(lineNo, `"judge" must be a block (put its keys on the following indented lines)`);
132	        judge = {};
133	      } else {
134	        (cfg as Record<string, unknown>)[key] = scalar(rest, key, lineNo);
135	      }
136	    } else if (item && inParticipants && participants) {
137	      const [, key, rest] = item;
138	      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
139	      participants.push({ [key]: scalar(rest, key, lineNo) });
140	    } else if (cont && inParticipants && participants) {
141	      const [, key, rest] = cont;
142	      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
143	      const current = participants[participants.length - 1];
144	      if (!current) fail(lineNo, `participant field before any "- " list item`);
145	      if (key in current) fail(lineNo, `duplicate participant key "${key}"`);
146	      current[key] = scalar(rest, key, lineNo);
147	    } else if (cont && inJudge && judge) {
148	      const [, key, rest] = cont;
149	      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
150	      if (key in judge) fail(lineNo, `duplicate judge key "${key}"`);
151	      judge[key] = scalar(rest, key, lineNo);
152	    } else {
153	      fail(lineNo, `cannot parse "${lines[i].trim()}" (this parser supports only flat "key: value" and a participants list)`);
154	    }
155	  }
156	
157	  if (participants) {
158	    for (const p of participants) {
159	      if (typeof p.adapter !== "string" || !ADAPTERS.has(p.adapter)) {
160	        throw new Error(`debate config: each participant needs "adapter: claude | agy | codex | pi | copilot-cli" (got ${JSON.stringify(p)})`);
161	      }
162	    }
163	    if (participants.length < 2) {
164	      throw new Error(`debate config: a debate needs at least 2 participants (got ${participants.length})`);
165	    }
166	    cfg.participants = participants as ParticipantSpec[];
167	  }
168	  if (judge) {
169	    if (typeof judge.adapter !== "string" || !ADAPTERS.has(judge.adapter)) {
170	      throw new Error(`debate config: the judge needs "adapter: claude | agy | codex | pi | copilot-cli" (got ${JSON.stringify(judge)})`);
171	    }
172	    cfg.judge = judge as ParticipantSpec;
173	  }
174	  if (cfg.rounds !== undefined && (!Number.isInteger(cfg.rounds) || cfg.rounds < 0)) {
175	    throw new Error(`debate config: "rounds" must be a non-negative integer`);
176	  }
177	  return cfg;
178	}

  1	#!/usr/bin/env node
  2	// CLI entry (Kaizen v0). Two run modes off ONE codebase:
  3	//   - from source:      node src/index.ts "<quaestio>" [--rounds N] [--repo path] [--config debate.yaml]
  4	//   - installed binary: disputatio "<quaestio>" ...   (npm install -g disputatio)
  5	// The quaestio is given inline by default; --file <path> reads it from a markdown file.
  6	// rounds/repo are named flags (--rounds/--repo), so the quaestio is the only positional.
  7	// The shebang lets npm's `bin` symlink exec this directly: Node ≥24 type-strips the .ts.
  8	
  9	import { mkdir, writeFile, readFile, readdir } from "node:fs/promises";
 10	import { execFile } from "node:child_process";
 11	import { promisify } from "node:util";
 12	import { claudeAdapter, agyAdapter, codexAdapter, piAdapter, copilotCliAdapter, type Participant } from "./adapters.ts";
 13	import { parseDebateConfig, type ParticipantSpec, type DebateConfig } from "./config.ts";
 14	import { runDebate, runFinalize, runContinuation, parseRespondeoStatus } from "./debate.ts";
 15	import { runDoctor, allHealthy, formatDiagnoses, CANARY_TIMEOUT_MS } from "./doctor.ts";
 16	import { resolveConfigText, userConfigPath, runInit } from "./install.ts";
 17	import { resolveQuaestioInput } from "./quaestio.ts";
 18	
 19	const execFileAsync = promisify(execFile);
 20	
 21	function usage(exitCode: number): never {
 22	  console.error('usage: disputatio "<quaestio>" [--rounds N] [--repo path] [--config debate.yaml]');
 23	  console.error("       disputatio --file <task-file.md> [--rounds N] [--repo path] [--config debate.yaml]");
 24	  console.error('       disputatio --continue "<answers>" [--debate <dir>] [--config debate.yaml]');
 25	  console.error("       disputatio --finalize [--debate <dir>] [--config debate.yaml]");
 26	  console.error("       disputatio --doctor [--config debate.yaml]");
 27	  console.error("       disputatio --init [--config debate.yaml] [--force]");
 28	  console.error("  quaestio   the question/task to debate, given inline as a string (quote it)");
 29	  console.error("  --file,-f  read the quaestio from a markdown file instead (for long descriptions)");
 30	  console.error('  --continue close the loop after a NEEDS_INPUT respondeo: re-judge the latest debate');
 31	  console.error("             with your answers (a string), then draft the deliverable if RESOLVED");
 32	  console.error("  --finalize (re)draft the final-report.md deliverable from a RESOLVED debate");
 33	  console.error("  --debate   target a specific .debate/<dir> for --continue/--finalize (default: latest)");
 34	  console.error("  --rounds   number of reaction rounds after proposals (default 1)");
 35	  console.error("  --repo     optional: agents gather read-only evidence in a throwaway git");
 36	  console.error("             worktree of this repo (git repos only; HEAD is what they see)");
 37	  console.error("  --budget   override the judge/synthesizer per-turn budget cap in USD (default: $5);");
 38	  console.error("             use when the redactio fails with 'Reached maximum budget'");
 39	  console.error("  --config   debate.yaml selecting participants/models/budgets + an optional judge");
 40	  console.error("             (see examples/debate.yaml — a TEMPLATE, never auto-loaded). When omitted,");
 41	  console.error(`             reads ${userConfigPath()} if present, else the built-in lineup: claude + codex, no judge`);
 42	  console.error("  --doctor   preflight: canary every participant CLI (runnable + authenticated),");
 43	  console.error("             report status, exit 0 if all healthy. Run this before a real debate.");
 44	  console.error("  --init     probe the lineup, resolve each CLI's real binary, and write the user");
 45	  console.error(`             config to ${userConfigPath()}. Run after authenticating each CLI. --force overwrites.`);
 46	  process.exit(exitCode);
 47	}
 48	
 49	const args = process.argv.slice(2);
 50	if (args.length === 0 || args[0] === "-h" || args[0] === "--help") usage(args.length === 0 ? 1 : 0);
 51	
 52	let configPath: string | undefined;
 53	let filePath: string | undefined;
 54	let roundsArg: string | undefined;
 55	let repoArg: string | undefined;
 56	let continueArg: string | undefined;
 57	let debateArg: string | undefined;
 58	let budgetArg: string | undefined;
 59	let finalizeMode = false;
 60	let doctorMode = false;
 61	let initMode = false;
 62	let force = false;
 63	const positionals: string[] = [];
 64	for (let i = 0; i < args.length; i++) {
 65	  if (args[i] === "--config") {
 66	    configPath = args[++i];
 67	    if (!configPath) usage(1);
 68	  } else if (args[i] === "--file" || args[i] === "-f") {
 69	    filePath = args[++i];
 70	    if (!filePath) usage(1);
 71	  } else if (args[i] === "--rounds") {
 72	    roundsArg = args[++i];
 73	    if (roundsArg === undefined) usage(1);
 74	  } else if (args[i] === "--repo") {
 75	    repoArg = args[++i];
 76	    if (!repoArg) usage(1);
 77	  } else if (args[i] === "--continue") {
 78	    continueArg = args[++i];
 79	    if (continueArg === undefined) usage(1);
 80	  } else if (args[i] === "--debate") {
 81	    debateArg = args[++i];
 82	    if (!debateArg) usage(1);
 83	  } else if (args[i] === "--finalize") {
 84	    finalizeMode = true;
 85	  } else if (args[i] === "--budget") {
 86	    budgetArg = args[++i];
 87	    if (!budgetArg || isNaN(Number(budgetArg)) || Number(budgetArg) <= 0) usage(1);
 88	  } else if (args[i] === "--doctor") {
 89	    doctorMode = true;
 90	  } else if (args[i] === "--init") {
 91	    initMode = true;
 92	  } else if (args[i] === "--force") {
 93	    force = true;
 94	  } else {
 95	    positionals.push(args[i]);
 96	  }
 97	}
 98	
 99	// Cross-vendor by design: claude→Anthropic, codex→OpenAI, agy→Google. Diversity is the
100	// point. The built-in default lineup is claude+codex (no judge — bare runs stay lean);
101	// the respondeo judge is reserved for configured runs (e.g. what `--init` writes).
102	const DEFAULT_SPECS: ParticipantSpec[] = [{ adapter: "claude" }, { adapter: "codex" }];
103	const DEFAULT_JUDGE: ParticipantSpec = { adapter: "claude", model: "opus", effort: "high", maxBudgetUsd: 5 };
104	
105	function buildParticipant(s: ParticipantSpec, timeoutMs: number): Participant {
106	  switch (s.adapter) {
107	    case "claude": return claudeAdapter(s.model ?? "sonnet", { maxBudgetUsd: s.maxBudgetUsd, timeoutMs, effort: s.effort });
108	    case "agy":
109	      // agy has no effort flag — effort is baked into the model name (e.g. "(High)").
110	      if (s.effort) console.error(`[disputatio] ⚠️ agy ignores "effort" — encode it in the model name (e.g. "Gemini 3.5 Flash (High)")`);
111	      return agyAdapter(s.model ?? "Gemini 3.5 Flash (High)", { timeoutMs });
112	    case "codex": return codexAdapter(s.model, { bin: s.bin, timeoutMs, effort: s.effort });
113	    case "pi": return piAdapter(s.model, { bin: s.bin, timeoutMs, effort: s.effort });
114	    case "copilot-cli": return copilotCliAdapter(s.model, { bin: s.bin, timeoutMs, effort: s.effort });
115	  }
116	}
117	
118	// --budget overrides maxBudgetUsd on judge/synthesizer turns only (claude-only flag).
119	// Precedence: --budget > config maxBudgetUsd > default $2. Debater budgets are config-only.
120	function withBudget(spec: ParticipantSpec): ParticipantSpec {
121	  return budgetArg !== undefined ? { ...spec, maxBudgetUsd: Number(budgetArg) } : spec;
122	}
123	
124	// --- --continue / --finalize helpers: read an existing debate back off disk ----------
125	// Respondeo files are versioned: respondeo.md (the first determination, = #1), then
126	// respondeo-2.md, respondeo-3.md, … one per --continue. The highest number is current.
127	function respondeoNum(name: string): number {
128	  const m = name.match(/^respondeo(?:-(\d+))?\.md$/);
129	  return m ? (m[1] ? Number(m[1]) : 1) : -1;
130	}
131	
132	// Default the debate target to the most RECENT .debate/debate-* (ids are ISO
133	// timestamps, so a lexicographic sort is chronological). Explicit --debate wins.
134	async function resolveDebateDir(explicit?: string): Promise<string> {
135	  if (explicit) return explicit;
136	  const entries = await readdir(".debate", { withFileTypes: true }).catch(() => []);
137	  const dirs = entries.filter((e) => e.isDirectory() && e.name.startsWith("debate-")).map((e) => e.name).sort();
138	  if (dirs.length === 0) {
139	    console.error("[disputatio] no .debate/debate-* directory found — run a debate first");
140	    process.exit(1);
141	  }
142	  return `.debate/${dirs.at(-1)}`;
143	}
144	
145	async function loadLatestRespondeo(dir: string): Promise<{ num: number; text: string }> {
146	  const names = (await readdir(dir).catch(() => [])).filter((n) => respondeoNum(n) > 0);
147	  if (names.length === 0) {
148	    console.error(`[disputatio] no respondeo found in ${dir} — was this debate run with a judge?`);
149	    process.exit(1);
150	  }
151	  const latest = names.sort((a, b) => respondeoNum(a) - respondeoNum(b)).at(-1)!;
152	  return { num: respondeoNum(latest), text: await readFile(`${dir}/${latest}`, "utf8") };
153	}
154	
155	// Recover the quaestio from a saved transcript. debate.ts writes the header as
156	// `## Task\n\n<task>` and then appends the proposals, so the quaestio runs up to the
157	// FIRST `## Proposal — `. We can't stop at the next `## ` — the task itself routinely
158	// contains `## CONTEXT` / `## TODO` subsections (that truncated it to the title alone).
159	function extractTask(debateMd: string): string {
160	  const m = debateMd.match(/## Task\n\n([\s\S]*?)\n## Proposal — /);
161	  return m ? m[1].trim() : "(quaestio not found in transcript)";
162	}
163	
164	// --init: probe the lineup, resolve each CLI's real binary, write the user config.
165	// Branch BEFORE resolving the runtime config: init REGENERATES the user config, so its
166	// basis is an explicit --config or the built-in defaults — it must NEVER read (and choke
167	// on) the existing ~/.config/disputatio/config.yaml. Parsing its own basis here is what
168	// lets `disputatio --init --force` recover from a user config the user broke by hand.
169	// With --config the judge carries through; with no config the default opus judge is
170	// seeded (so a set-up install gets the full scholastic protocol).
171	if (initMode) {
172	  const basis: DebateConfig = configPath ? parseDebateConfig(await readFile(configPath, "utf8")) : {};
173	  const initSpecs = basis.participants ?? DEFAULT_SPECS;
174	  const initJudge = configPath ? basis.judge : DEFAULT_JUDGE;
175	  console.error(`[disputatio] init — probing: ${initSpecs.map((s) => s.adapter).join(", ")}`);
176	  const res = await runInit(initSpecs, initJudge, userConfigPath(), { force, deps: { buildParticipant } });
177	  console.error(res.report);
178	  process.exit(res.exitCode);
179	}
180	
181	// Config resolution (see install.ts): --config → ~/.config/disputatio/config.yaml →
182	// built-in lineup. The shipped examples/debate.yaml is a TEMPLATE, never auto-loaded —
183	// that coupling was the P2 footgun (its host-specific bin: broke other machines).
184	const { text: cfgText, source: cfgSource } = await resolveConfigText(configPath);
185	const cfg: DebateConfig = cfgText !== null ? parseDebateConfig(cfgText) : {};
186	
187	const specs: ParticipantSpec[] = cfg.participants ?? DEFAULT_SPECS;
188	const timeoutMs = (cfg.timeoutMinutes ?? 10) * 60_000;
189	
190	// --doctor: preflight only — needs the lineup (+ optional --config), nothing else.
191	// Branch BEFORE the task-file/rounds/repo logic so `--doctor` never gets mistaken
192	// for a task file. Short canary timeout: a hung preflight is a broken preflight.
193	// The judge is an agent that must be runnable + authenticated like any other — canary it too.
194	if (doctorMode) {
195	  console.error(`[disputatio] config: ${cfgSource}`);
196	  const participants = specs.map((s) => buildParticipant(s, CANARY_TIMEOUT_MS));
197	  if (cfg.judge) participants.push(buildParticipant(cfg.judge, CANARY_TIMEOUT_MS));
198	  console.error(`[disputatio] doctor — canary: ${participants.map((p) => p.id).join(", ")}`);
199	  const diagnoses = await runDoctor(participants);
200	  console.error(formatDiagnoses(diagnoses));
201	  process.exit(allHealthy(diagnoses) ? 0 : 1);
202	}
203	
204	// --continue / --finalize close the human-in-the-loop: they re-enter an EXISTING debate
205	// on disk (no new debate runs). Both need the judge/synthesizer — fall back to the
206	// built-in opus judge when the config has none (the default lineup is judge-less, but
207	// closing the loop is intrinsically a judge act). Branch BEFORE quaestio resolution:
208	// the quaestio is recovered from the saved transcript, not the CLI.
209	if (continueArg !== undefined || finalizeMode) {
210	  const dir = await resolveDebateDir(debateArg);
211	  const { num, text: prevDetermination } = await loadLatestRespondeo(dir);
212	  const transcript = await readFile(`${dir}/debate.md`, "utf8");
213	  const quaestio = extractTask(transcript);
214	  const judge = buildParticipant(withBudget(cfg.judge ?? DEFAULT_JUDGE), timeoutMs);
215	  console.error(`[disputatio] config: ${cfgSource}`);
216	
217	  // --repo grounds ONLY the redactio (the deliverable), in a read-only worktree of HEAD.
218	  // The re-judge stays transcript-only (respondeo invariant: it trusts the human's answers,
219	  // it does not re-litigate against the repo). So --repo is meaningful here only because a
220	  // RESOLVED continuation, and every --finalize, ends in a redactio. Validate it's git.
221	  const finalizeRepo = repoArg ?? cfg.repo;
222	  if (finalizeRepo) {
223	    try {
224	      await execFileAsync("git", ["-C", finalizeRepo, "rev-parse", "--is-inside-work-tree"]);
225	    } catch {
226	      console.error(`[disputatio] ${finalizeRepo} is not a git repository — redactio evidence mode requires git (read-only worktree of HEAD)`);
227	      process.exit(1);
228	    }
229	    console.error(`[disputatio] redactio will ground the deliverable in ${finalizeRepo} (read-only worktree of HEAD)`);
230	  }
231	
