 63	export type AgentResult =
 64	  | { ok: true; text: string; costUsd?: number; raw?: CliCapture }
 65	  | { ok: false; error: string; budgetExhausted?: true; raw?: CliCapture };
 66	
 67	export type Participant = {
 68	  id: string;
 69	  display: string;
 70	  vendor: string; // used for the cross-vendor sanity check (diversity is the whole point)
 71	  run: (prompt: string, cwd: string) => Promise<AgentResult>;
 72	};
 73	
 74	// exit 126/127 = the shell could not run the binary at all (e.g. a stale asdf
 75	// shim shadowing the real install) — a setup problem, not an agent failure.
 76	function spawnFailure(r: CliCapture): string | null {
 77	  if (r.code === 126 || r.code === 127) {
 78	    return `binary not runnable (exit ${r.code}) — check PATH / asdf shims, or set 'bin' in debate.yaml. stderr: ${r.stderr.slice(0, 200)}`;
 79	  }
 80	  return null;
 81	}
