 16	// --- resolveBinary (pure) -------------------------------------------------------------
 17	
 18	test("resolveBinary: PATH binary works → ok, no pin, alternatives untouched", async () => {
 19	  let calls = 0;
 20	  const res = await resolveBinary("codex", ["/opt/homebrew/bin/codex"], async (bin) => { calls++; return bin === "codex"; });
 21	  assert.deepEqual(res, { ok: true, tried: ["codex"] });
 22	  assert.equal(calls, 1); // short-circuits — never canaries the alternative
 23	});
