 25	test("resolveBinary: PATH binary fails, an alternative works → pin that alternative", async () => {
 26	  const res = await resolveBinary("codex", ["/n/a/codex", "/opt/homebrew/bin/codex"], async (bin) => bin === "/opt/homebrew/bin/codex");
 27	  assert.equal(res.ok, true);
 28	  assert.equal(res.bin, "/opt/homebrew/bin/codex");
 29	});
