 37	// --- runInit (DI) ---------------------------------------------------------------------
 38	
 39	// A stub lineup factory: the canary verdict is whether the spec's effective binary is in
 40	// `working`. runInit's default canary is runIsolated → p.run, which for a stub never
 41	// spawns a real CLI.
 42	function stubBuild(working: Set<string>) {
 43	  return (spec: ParticipantSpec): Participant => ({
 44	    id: spec.adapter,
 45	    display: spec.adapter,
 46	    vendor: spec.adapter,
 47	    run: async () => (working.has(spec.bin ?? spec.adapter) ? { ok: true, text: "pong" } : { ok: false, error: "stale shim" }),
 48	  });
 49	}
