 51	const JUDGE: ParticipantSpec = { adapter: "claude", model: "opus", effort: "high", maxBudgetUsd: 2 };
 52	const tmpCfg = () => join(tmpdir(), `disputatio-init-${process.pid}-${Math.floor(performance.now())}.yaml`);
 53	
 54	test("runInit: codex stale shim → brew bin pinned; claude on PATH → no bin; judge seeded", async () => {
 55	  const cfgPath = tmpCfg();
 56	  try {
 57	    const res = await runInit(
 58	      [{ adapter: "claude" }, { adapter: "codex" }],
 59	      JUDGE,
 60	      cfgPath,
 61	      { force: true, deps: {
 62	        buildParticipant: stubBuild(new Set(["claude", "/opt/homebrew/bin/codex"])),
 63	        findAlternatives: async (bin) => (bin === "codex" ? ["/opt/homebrew/bin/codex"] : []),
 64	      } },
 65	    );
 66	    assert.equal(res.exitCode, 0);
 67	    const written = await readFile(cfgPath, "utf8");
 68	    assert.match(written, /adapter: codex/);
 69	    assert.match(written, /bin: \/opt\/homebrew\/bin\/codex/); // pinned because PATH codex failed
 70	    // claude block must NOT carry a bin (PATH binary worked)
 71	    const claudeBlock = written.slice(written.indexOf("adapter: claude"), written.indexOf("adapter: codex"));
 72	    assert.ok(!/bin:/.test(claudeBlock), `claude should have no bin, got: ${claudeBlock}`);
 73	    // judge seeded
 74	    assert.match(written, /judge:/);
 75	    assert.match(written, /model: opus/);
 76	  } finally {
 77	    await rm(cfgPath, { force: true });
 78	  }
 79	});
